    async def update(
        self,
        id: str,
        *,
        revision_number: str,
        vendor_id: str | NotGiven = NOT_GIVEN,
        class_id: str | NotGiven = NOT_GIVEN,
        inventory_site_id: str | NotGiven = NOT_GIVEN,
        ship_to_entity_id: str | NotGiven = NOT_GIVEN,
        document_template_id: str | NotGiven = NOT_GIVEN,
        transaction_date: _dt.date | NotGiven = NOT_GIVEN,
        ref_number: str | NotGiven | None = NOT_GIVEN,
        vendor_address: AddressUpdateInput | NotGiven = NOT_GIVEN,
        shipping_address: AddressUpdateInput | NotGiven = NOT_GIVEN,
        terms_id: str | NotGiven = NOT_GIVEN,
        due_date: _dt.date | NotGiven = NOT_GIVEN,
        expected_date: _dt.date | NotGiven = NOT_GIVEN,
        shipping_method_id: str | NotGiven = NOT_GIVEN,
        shipment_origin: str | NotGiven | None = NOT_GIVEN,
        is_manually_closed: bool | NotGiven = NOT_GIVEN,
        memo: str | NotGiven | None = NOT_GIVEN,
        vendor_message: str | NotGiven | None = NOT_GIVEN,
        is_queued_for_print: bool | NotGiven = NOT_GIVEN,
        is_queued_for_email: bool | NotGiven = NOT_GIVEN,
        other_custom_field1: str | NotGiven | None = NOT_GIVEN,
        other_custom_field2: str | NotGiven | None = NOT_GIVEN,
        exchange_rate: float | NotGiven = NOT_GIVEN,
        lines: Sequence[PurchaseOrderLineUpdateInput] | NotGiven = NOT_GIVEN,
        line_groups: Sequence[PurchaseOrderLineGroupUpdateInput] | NotGiven = NOT_GIVEN,
        end_user_id: str | None = None,
        conductor_end_user_id: str | None = None,
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
        server_timeout: int | None = None,
    ) -> PurchaseOrder:
        """Update a purchase order.

        Changes the fields you send on an existing purchase order and leaves omitted fields unchanged. Requires the current `revisionNumber`. A stale `revisionNumber` returns `409 QBD_REVISION_NUMBER_STALE`: retrieve the purchase order, reapply your change and send the new revision. Sending a line array replaces all existing lines of that kind. Line arrays you omit stay unchanged: when you send only some of them, the API first reads the transaction (a separate read in the request log) and keeps the omitted lines by ID, because QuickBooks would otherwise delete them. See [Updates and line items](https://www.desktopaccountingapi.com/docs/quickbooks/updates-and-line-items/).

        Operation ``qbd.purchaseOrders.update``: ``POST /v1/quickbooks-desktop/purchase-orders/{id}``.

        Args:
            id: QuickBooks ID of the purchase order.
            revision_number: Current revision of this purchase order. Send it unchanged when updating; a stale value is rejected. QuickBooks changes it at most once per second, so a second edit within the same second keeps the same value. This API spaces its own consecutive writes to one object by over a second; edits made elsewhere in the same second are not detected.
            vendor_id: ID of the vendor for this purchase order.
            class_id: ID of the class for this purchase order.
            inventory_site_id: ID of the inventory site for this purchase order. Cannot be combined with shipToEntityId.
            ship_to_entity_id: ID of the ship to entity for this purchase order. Cannot be combined with inventorySiteId.
            document_template_id: ID of the document template for this purchase order.
            transaction_date: Date of this purchase order (YYYY-MM-DD).
            ref_number: Reference number of this purchase order, such as an invoice or check number. Case-sensitive. Pass ``None`` to clear it.
            vendor_address: Vendor address details for this purchase order.
            shipping_address: Shipping address for this purchase order.
            terms_id: ID of the terms for this purchase order.
            due_date: Date payment of this purchase order is due (YYYY-MM-DD).
            expected_date: Expected date (YYYY-MM-DD).
            shipping_method_id: ID of the shipping method for this purchase order.
            shipment_origin: Shipment origin of this purchase order. Pass ``None`` to clear it.
            is_manually_closed: Whether this purchase order is manually closed.
            memo: Internal memo for this purchase order; shown in reports, not on printed forms. Pass ``None`` to clear it.
            vendor_message: Vendor message of this purchase order. Pass ``None`` to clear it.
            is_queued_for_print: Whether this purchase order is in the queue of forms to print.
            is_queued_for_email: Whether this purchase order is in the queue of forms to email.
            other_custom_field1: Built-in "Other 1" text field on this purchase order. Pass ``None`` to clear it.
            other_custom_field2: Built-in "Other 2" text field on this purchase order. Pass ``None`` to clear it.
            exchange_rate: Exchange rate from this purchase order's currency to the home currency.
            lines: Line items of this purchase order. When present, replaces this array: keep an existing entry by sending its id (an id alone leaves it unchanged), add one with id "-1"; existing entries you leave out are deleted. Omit the array to keep these entries unchanged, also when you send lineGroups: the API then reads the purchase order first and keeps every existing entry of each omitted array by ID. An empty array deletes them all, as long as the purchase order keeps at least one line.
            line_groups: Group lines of this purchase order: each expands an item group into its component lines. When present, replaces this array: keep an existing entry by sending its id (an id alone leaves it unchanged), add one with id "-1"; existing entries you leave out are deleted. Omit the array to keep these entries unchanged, also when you send lines: the API then reads the purchase order first and keeps every existing entry of each omitted array by ID. An empty array deletes them all, as long as the purchase order keeps at least one line.
            end_user_id: End user (``eu_...``) whose QuickBooks company file to use. Defaults to the client's ``end_user_id``.
            conductor_end_user_id: Alias of ``end_user_id`` with Conductor's name, for code ported from ``conductor-py``. Passing both with different values raises ``DaapiError``.
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.
            server_timeout: Seconds the API waits for QuickBooks before answering (``Daapi-Timeout-Seconds``, 1-300). Defaults to the client's ``server_timeout`` or the API default.

        Returns:
            The PurchaseOrder object.
        """
        return await self._client._request(
            _QBD_PURCHASE_ORDERS_UPDATE,
            "POST",
            "/v1/quickbooks-desktop/purchase-orders/" + _pp("id", id),
            cast_to=PurchaseOrder.from_wire,
            body={
                "revisionNumber": revision_number,
                "vendorId": vendor_id,
                "classId": class_id,
                "inventorySiteId": inventory_site_id,
                "shipToEntityId": ship_to_entity_id,
                "documentTemplateId": document_template_id,
                "transactionDate": transaction_date,
                "refNumber": ref_number,
                "vendorAddress": vendor_address,
                "shippingAddress": shipping_address,
                "termsId": terms_id,
                "dueDate": due_date,
                "expectedDate": expected_date,
                "shippingMethodId": shipping_method_id,
                "shipmentOrigin": shipment_origin,
                "isManuallyClosed": is_manually_closed,
                "memo": memo,
                "vendorMessage": vendor_message,
                "isQueuedForPrint": is_queued_for_print,
                "isQueuedForEmail": is_queued_for_email,
                "otherCustomField1": other_custom_field1,
                "otherCustomField2": other_custom_field2,
                "exchangeRate": exchange_rate,
                "lines": lines,
                "lineGroups": line_groups,
            },
            end_user_id=end_user_id,
            conductor_end_user_id=conductor_end_user_id,
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
            server_timeout=server_timeout,
        )
